    @staticmethod
    def _prove(kb: KnowledgeBase, goal: Atom, subst: Dict[str, str], 
               depth: int, visited: Set[str]) -> Optional[Dict[str, str]]:
        """Backward chaining proof - returns substitution if successful, None otherwise"""
        if depth <= 0:
            return None

        goal = goal.apply_substitution(subst)
        goal_str = str(goal)

        if goal_str in visited:
            return None
        visited.add(goal_str)

        # Try facts
        for fact in kb.facts:
            new_subst = UnificationEngine.unify(goal, fact, subst)
            if new_subst is not None:
                return new_subst

        # Try rules
        for rule in kb.rules:
            renamed_rule = EntailmentChecker._rename_rule_variables(rule)
            head_subst = UnificationEngine.unify(goal, renamed_rule.head, subst)

            if head_subst is not None:
                result_subst = EntailmentChecker._prove_conjunction(kb, renamed_rule.body, 
                                                       head_subst, depth - 1, visited)
                if result_subst is not None:
                    return result_subst

        return None

    @staticmethod
    def _prove_conjunction(kb: KnowledgeBase, goals: List[Atom], 
                          subst: Dict[str, str], depth: int, visited: Set[str]) -> Optional[Dict[str, str]]:
        """Prove conjunction of goals - returns final substitution if successful"""
